def f(x):
    """Returns the sum of all integers from 1 to x if x is positive, or x + 6 if x is negative.
    Special case: when x is a multiple of 10, returns the sum divided by 10."""
    if x < 0:
        return x + 6
    total = x * (x + 1) // 2
    if x % 10 == 0:
        return total // 10
    return total
